TLM.f("Sancti/02-05",{"officium":"S. Agathæ Virginis et Martyris","rule":["vide C6;","Gloria"],"ruleInherited":["Gloria"],"fallback":"Commune/C6","from":{"GradualeP":"Commune/C6"},"sections":{"Introitus":[{"k":"text","la":"Gaudeámus omnes in Dómino, diem festum celebrántes sub honóre beátæ Agathæ Vírginis et Martyris: de cujus passióne gaudent Angeli et colláudant Fílium Dei."},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Gaudeámus omnes in Dómino, diem festum celebrántes sub honóre beátæ Agathæ Vírginis et Martyris: de cujus passióne gaudent Angeli et colláudant Fílium Dei."}],"Oratio":[{"k":"text","la":"Deus, qui inter cétera poténtiæ tuæ mirácula étiam in sexu frágili victóriam martýrii contulísti: concéde propítius; ut, qui beátæ Agathæ Vírginis et Mártyris tuæ natalítia cólimus, per ejus ad te exémpla gradiámur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corinthios"},{"k":"ref","la":"1 Cor 1:26-31"},{"k":"text","la":"Fratres: Vidéte vocatiónem vestram: quia non multi sapiéntes secúndum carnem, non multi poténtes, non multi nóbiles: sed quæ stulta sunt mundi elégit Deus, ut confúndat sapiéntes: et infírma mundi elégit Deus, ut confúndat fórtia: et ignobília mundi et contemptibília elégit Deus, et ea quæ non sunt, ut ea quæ sunt destrúeret: ut non gloriétur omnis caro in conspéctu ejus. Ex ipso autem vos estis in Christo Jesu, qui factus est nobis sapiéntia a Deo, et justítia, et sanctificátio, et redémptio: ut, quemádmodum scriptum est: Qui gloriátur, in Dómino gloriétur."}],"Graduale":[{"k":"ref","la":"Ps 45:6 et 5"},{"k":"text","la":"Adjuvábit eam Deus vultu suo: Deus in médio ejus, non commovébitur."},{"k":"text","la":"Flúminis impetus lætíficat civitátem Dei: sanctificávit tabernáculum suum Altíssimus. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 118:46"},{"k":"text","la":"Loquébar de testimóniis tuis in conspéctu regum, et non confundébar. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15; 44:16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 45:6 et 5"},{"k":"text","la":"Adjuvábit eam Deus vultu suo: Deus in médio ejus, non commovébitur."},{"k":"text","la":"Flúminis impetus lætíficat civitátem Dei: sanctificávit tabernáculum suum Altíssimus.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et fiébant, mitténtes semina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 19:3-12"},{"k":"text","la":"In illo témpore: Accessérunt ad Jesum pharisǽi, tentántes eum et dicéntes: Si licet hómini dimíttere uxórem suam quacúmque ex causa? Qui respóndens, ait eis: Non legístis, quia, qui fecit hóminem ab inítio, másculum et féminam fecit eos? et dixit: Propter hoc dimíttet homo patrem, et matrem, et adhærébit uxóri suæ, et erunt duo in carne una. Itaque jam non sunt duo, sed una caro. Quod ergo Deus conjúnxit, homo non séparet. Dicunt illi: Quid ergo Móyses mandávit dare libéllum repúdii, et dimíttere? Ait illis: Quóniam Móyses ad durítiam cordis vestri permísit vobis dimíttere uxóres vestras: ab inítio autem non fuit sic. Dico autem vobis, quia, quicúmque dimíserit uxórem suam, nisi ob fornicatiónem, et áliam dúxerit, mœchátur: et qui dimíssam dúxerit, mœchátur. Dicunt ei discípuli ejus: Si ita est causa hóminis cum uxóre, non expédit núbere. Qui dixit illis: Non omnes cápiunt verbum istud, sed quibus datum est. Sunt enim eunúchi, qui de matris útero sic nati sunt; et sunt eunúchi, qui facti sunt ab homínibus; et sunt eunúchi, qui seípsos castravérunt propter regnum cœlórum. Qui potest cápere, cápiat."}],"Offertorium":[{"k":"ref","la":"Ps 44:15"},{"k":"text","la":"Afferéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi."}],"Secreta":[{"k":"text","la":"Súscipe, Dómine, múnera, quæ in beátæ Agathæ Vírginis et Mártyris tuæ sollemnitáte deférimus: cujus nos confídimus patrocínio liberári."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"text","la":"Qui me dignátus est ab omni plaga curáre et mamíllam meam meo péctori restitúere, ipsum ínvoco Deum vivum."}],"Postcommunio":[{"k":"text","la":"Auxiliéntur nobis, Dómine, sumpta mystéria: et, intercedénte beáta Agatha Vírgine et Mártyre tua, sempitérna protectióne confírment."},{"k":"macro","name":"Per Dominum"}]},"hr":{"6da2c159d5466b89":{"t":"Ps 44, 2\nRadujmo se svi u Gospodinu slaveći blagdan na čast blažene Agate djevice i mučenice, radi čijeg se mučeništva raduju anđeli i hvale Sina Božjega. (Ps 44, 2). Iz srca mi navire radosna riječ, pripovijedam djela svoja Kralju.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\nRadujmo se svi u Gospodinu slaveći blagdan na čast blažene Agate djevice i mučenice, radi čijeg se mučeništva raduju anđeli i hvale Sina Božjega.","kn":"Radujmo se svi u Gospodinu -svetkujući blagdan na čast blažene Agate, djevice i mučenice- “Učeništvu raduju anđeli i slave Srna Božjega. (Ps. 44, 2). Iz mog srca izvire sliva “.'RlJujml.\"!^^\" namijenjena Kralju!","knRef":"Kniewald 1942, str. 502–503 (snimka 252) (OCR)"},"ee52bd9b37830382":{"t":"<i>Pomolimo se</i>.\nBože, koje si između ostalih čudesa svoje moći dao i slabom spolu mučeničku pobjedu, dopusti blagostivo da mi koji slavimo rođendan za nebo blažene Agate, tvoje djevice i mučenice, idemo k tebi po njezinu primjeru.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si među ostalim čudesima svoje moći i slabom spolu poda-o pobjedu mučeništva, dopusti milostivo, da svetkujući rođeni dan blažene I., djevice i mučenice, slijedimo njezin primjer i tako -dođemo k Tebi, po G. *","knRef":"Kniewald 1942, str. 820–821 (snimka 411) (OCR)"},"fdbec77ea21c181d":{"t":"1 Kor 1, 26-31\nČitanje Poslanice bl. Pavla apostola Korinćanima: Braćo, promatrajte svoje zvanje! Nema tu, kako ljudi drže mnogo mudrih, ni mnogo jakih, ni mnogo plemenitih, nego što svijet drži ludim Bog izabra, da postidi mudre. I što je pred svijetom slabo Bog izabra, da posrami jake, i što je u očima svijeta neplemenito, i ono čega nema Bog izabra, da uništi ono što jest, da se nitko ne hvali pred Bogom. I vi ste, što jeste, u Isusu Kristu koji je za nas Božja mudrost, pravda, posveta, otkup, da, kao što je pisano: Koji god se hvali, neka se hvali u Gospodinu."},"a317618009abc324":{"t":"Ps 45, 6 i 5\nSnaga joj je promatranje lica Božjega. Bog je u njoj i neće se pokolebati. Nabujala rijeka veseli grad Božji. Svevišnji je posvetio prebivalište svoje.\n\nPs 125, 5-6\nKoji siju u suzama u radosti će žeti. Tužno koračaju i plaču noseći sjeme za sjetvu. Ali će doći, doći će s klicanjem noseći snopove svoje."},"2ed949393f646d1b":{"t":"Mt 19, 3-12\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme pristupe k Isusu farizeji i iskušavajući ga upitaju: Smije li muž otpustiti svoju ženu s bilo kojeg razloga? On im odgovori: Niste li čitali da je Stvoritelj u početku učinio muško i žensko, i rekao: Zato će čovjek ostaviti oca i majku i prionuti svojoj ženi i dvoje će biti jedno tijelo? Prema tome oni više nisu dva, nego jedno tijelo. Što je sjedinio Bog, neka ne rastavlja čovjek! Oni reknu: A zašto je Mojsije naredio da se dade rastavno pismo i otpusti? On odgovori: Mojsije vam je zbog vašeg tvrdog srca dopustio da se rastavite od svoje žene, ali od početka nije bilo tako. Zato vam ja kažem: Tko otpusti svoju ženu, pa i zbog preljuba, i oženi se drugom, sam čini preljub kao i tko se oženi otpuštenicom jednako čini preljub. Nato mu njegovi učenici reknu: Ako je tako čovjeku sa ženom, bolje se ne ženiti. On im odgovori: Svi toga ne shvaćaju, nego samo oni kojima je dano. Ima samaca koji su već rođeni takvi, ima ih koje su onesposobili ljudi, a ima i takvih koji se odriču ženidbe radi nebeskog kraljevstva. Neka to shvati, tko može shvatiti!"},"3438908276860a78":{"t":"Ps 44, 15\nZa njom će poći pred Kralja djevice. Drugarice će njezine poći k tebi."},"c4e6b496062502b2":{"t":"Primi, Gospodine, darove koje ti o svetkovini blažene Agate tvoje djevice i mučenice, prinosimo s pouzdanjem da ćemo se osloboditi po njezinoj zaštiti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, darove, što Ti ih prinosimo o svetkovini blažene I., djevice i mučenice uz'dajući se, da će na-s -njezin zagovor izbaviti. Po G. n.","knRef":"Kniewald 1942, str. 822–823 (snimka 412) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"e4d88b8e0712e7ea":{"t":"Zazivam Boga živoga koji se udostojao ozdraviti me od svake rane i izliječiti moje prsi.","kn":"Onaj, koji se dostojao čudesno izliječiti moje rane, njega zazivam, Boga živoga.","knRef":"Kniewald 1942, str. 504–505 (snimka 253) (OCR)"},"7c9bd78a131e16c2":{"t":"<i>Pomolimo se</i>.\nPrimljena otajstva, Gospodine, bila nam na pomoći i zagovorom blažene Agate, tvoje djevice i mučenice, neka nas neprestano štite i jačaju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Neka na-m. Gospodine, pomognu primljena otajstva, da njihovim učinkom i zagovorom blažene I., djevice i mučenice, uživamo Tvoju vječnu z-aštitu. Po G. n.","knRef":"Kniewald 1942, str. 822–823 (snimka 412) (OCR)"},"cd0d6becb7dd6136":null}});
